export const store = { applied: {}, pending: {} };

/**
 * Apply a job by id.
 * - Idempotent: calling again with the same id does nothing.
 * - Records partial failures so a retry can resume.
 * - Never double‑applies the same id.
 */
export function applyJob(id, work) {
  // If already applied, nothing to do.
  if (store.applied[id]) {
    return;
  }

  // Attempt the work; on error record pending state.
  try {
    const result = work();
    // Record successful application.
    store.applied[id] = (store.applied[id] || 0) + 1;
    // Clean up any pending record.
    delete store.pending[id];
    return result;
  } catch (e) {
    // Store failure reason for possible retry.
    store.pending[id] = e;
    // Do not mark as applied.
    throw e;
  }
}",
