      "content": "import test from 'node:test';
import assert from 'node:assert/strict';
import { applyJob, store } from './jobs.js';

test('applies once', () => {
  // Reset store state.
  Object.keys(store.applied).forEach(k => delete store.applied[k]);
  Object.keys(store.pending).forEach(k => delete store.pending[k]);
  assert.equal(applyJob('j1', () => 1), 1);
});

test('duplicate apply does nothing', () => {
  // Apply first time.
  applyJob('j2', () => 42);
  // Apply again – should be a no‑op.
  assert.equal(store.applied['j2'], 1);
});

test('records partial failure and can resume', async () => {
  // Ensure clean state.
  Object.keys(store.applied).forEach(k => delete store.applied[k]);
  Object.keys(store.pending).forEach(k => delete store.pending[k]);

  // Simulate a failure on first attempt.
  const failure = new Error('boom');
  try {
    applyJob('j3', () => { throw failure; });
  } catch (e) {
    assert.strictEqual(e, failure);
  }

  // Verify pending record exists.
  assert.strictEqual(store.pending['j3'], failure);

  // Retry – should succeed now.
  const result = applyJob('j3', () => 7);
  assert.strictEqual(result, 7);
  // After successful retry, it should be marked applied.
  assert.strictEqual(store.applied['j3'], 1);
  // No pending record should remain.
  assert.strictEqual(store.pending['j3'], undefined);
});

test('idempotent after failure', () => {
  // Apply a job that previously failed and was retried.
  applyJob('j4', () => 3);
  // Apply again – should be a no‑op.
  assert.equal(applyJob('j4', () => 3), undefined);
});

test('cannot double‑apply same id', () => {
  // First successful apply.
  applyJob('j5', () => 5);
  // Capture the applied count.
  const firstCount = store.applied['j5'];
  // Attempt duplicate apply.
  const result = applyJob('j5', () => 99);
  // No error, no extra count.
  assert.strictEqual(result, undefined);
  assert.strictEqual(store.applied['j5'], firstCount);
});

test('pending cleanup after success', () => {
  // Apply a job that will succeed.
  applyJob('j6', () => 11);
  // Ensure no pending entry.
  assert.strictEqual(store.pending['j6'], undefined);
});

test('overwrites stale pending with new failure', () => {
  // First failure.
  const err1 = new Error('first');
  try {
    applyJob('j7', () => { throw err1; });
  } catch (e) {
    assert.strictEqual(e, err1);
  }
  assert.strictEqual(store.pending['j7'], err1);

  // New failure on retry.
  const err2 = new Error('second');
  try {
    applyJob('j7', () => { throw err2; });
  } catch (e) {
    assert.strictEqual(e, err2);
  }
  // Pending should now hold the latest error.
  assert.strictEqual(store.pending['j7'], err2);
});

test('work can be sync or async', async () => {
  // Async success.
  await applyJob('j8', async () => {
    await new Promise(r => setTimeout(r, 10));
    return 13;
  });
  assert.strictEqual(store.applied['j8'], 1);

  // Async failure.
  const asyncErr = new Error('async boom');
  try {
    await applyJob('j9', async () => {
      await new Promise(r => setTimeout(r, 5));
      throw asyncErr;
    });
  } catch (e) {
    assert.strictEqual(e, asyncErr);
  }
  assert.strictEqual(store.pending['j9'], asyncErr);
});

test('cannot apply with missing id argument', () => {
  assert.throws(() => applyJob(undefined, () => 1), TypeError);
});

test('cannot apply with missing work argument', () => {
  assert.throws(() => applyJob('missing-work', undefined), TypeError);
});

test('work result is returned only on success', () => {
  const result = applyJob('j10', () => 999);
  assert.strictEqual(result, 999);
});

test('applied counter increments only on first success', () => {
  // First apply.
  applyJob('j11', () => 1);
  assert.strictEqual(store.applied['j11'], 1);
  // Retry – should not increment.
  applyJob('j11', () => 2);
  assert.strictEqual(store.applied['j11'], 1);
});

test('pending state is cleared after successful retry', () => {
  const fail = new Error('fail');
